'Enable_Pos_Salesperson_Switch_Hint' => 'logout မလုပ်ဘဲ အရောင်းကို အခြားဝန်ထမ်းထံ သတ်မှတ်နိုင်ရန် POS မျက်နှာပြင်တွင် အရောင်းဝန်ထမ်း ရွေးချယ်ကိရိယာ ပြပါ။ ရွေးထားသော အရောင်းဝန်ထမ်းကို ပြေစာတွင် သိမ်းဆည်းပြီး အရောင်းအစီရင်ခံစာများတွင် အသုံးပြုသည်; လက်ရှိ POS session မပြောင်းလဲပါ။',

'Wallet_Payment_Method_Missing' => 'Wallet ငွေပေးချေမှုနည်းလမ်း မရှိပါ',
'Wallet_Payment_Method_Missing_Help' => '"Wallet" ဟု အတိအကျ အမည်ပေးထားသော ငွေပေးချေမှုနည်းလမ်း မတွေ့ပါ။ POS wallet ငွေပေးချေမှုကို ဤအမည်ဖြင့် ကိုက်ညီစေသောကြောင့် ဤနေရာတွင် "Wallet" ဟု အမည်ပေးထားသော ငွေပေးချေမှုနည်းလမ်း မထည့်မချင်း ဖောက်သည်များ wallet ဖြင့် ပေးချေ၍ မရပါ:',

'Show_Previous_Dues_Line' => 'ယခင် ပေးရန်ကျန် လိုင်း ပြရန်',
'Show_Previous_Dues_Line_Desc' => 'ဤအရောင်းမတိုင်မီ ဖောက်သည် ပေးရန်ရှိသော လက်ကျန်။ သုညထက် ကြီးသည့်အခါသာ ပုံနှိပ်သည်။',
'Show_Net_Balance_Line' => 'အသားတင် လက်ကျန် လိုင်း ပြရန်',
'Show_Net_Balance_Line_Desc' => 'ယခင် ပေးရန်ကျန်နှင့် ဤအရောင်းတွင် ပေးရန်ကျန်ဆဲ ပမာဏ ပေါင်းလဒ်။ ယခင် ပေးရန်ကျန် သုညထက် ကြီးသည့်အခါသာ ပုံနှိပ်သည်။',

'QZ_Tray_Printer' => 'QZ Tray (ဤကွန်ပျူတာရှိ ပရင်တာ)',
'QZ_Printer_Name_Hint' => 'QZ Tray run နေသော ကွန်ပျူတာတွင် ပေါ်သည့်အတိုင်း ပရင်တာအမည်။ ထိုကွန်ပျူတာ၏ မူလပရင်တာကို အသုံးပြုရန် ဗလာထားပါ။ ပရင်တာများ ရှာဖွေရန် ⟳ ကို နှိပ်ပါ။',
'QZ_Not_Running' => 'QZ Tray သည် ဤကွန်ပျူတာတွင် run မနေပါ။ qz.io မှ ထည့်သွင်းပြီး run ထားပါ၊ ထို့နောက် QZ က မေးသည့်အခါ ဤဝက်ဘ်ဆိုက်ကို ခွင့်ပြုပါ။',
'Detect_Printers' => 'ပရင်တာများ ရှာဖွေရန်',
'QZ_Download_Cert' => 'လက်မှတ် ဒေါင်းလုဒ်ရန် (override.crt)',
'QZ_Setup_Title' => 'QZ Tray ပုံနှိပ်ခြင်း စနစ်ထည့်သွင်းနည်း (တံဆိပ်ပုံနှိပ်သော ကွန်ပျူတာတိုင်းတွင် တစ်ကြိမ်)',
'QZ_Step_Install' => '1. ဤကွန်ပျူတာတွင် QZ Tray ကို ထည့်သွင်းပါ — qz.io မှ အခမဲ့ ဒေါင်းလုဒ်လုပ်ပြီး စတင်ကာ run ထားပါ (Windows တွင် system tray၊ macOS တွင် menu bar ၌ ရှိသည်)။',
'QZ_Step_Connect' => '2. သင့်တံဆိပ်ပရင်တာကို USB ဖြင့် ချိတ်ဆက်ပြီး operating system တွင် ထည့်သွင်းထားကြောင်း စစ်ဆေးပါ (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners)။',
'QZ_Step_Detect' => '3. ဤကွန်ပျူတာရှိ ပရင်တာများကို ရှာရန် အထက်ရှိ "Printer name" ဘေးရှိ ⟳ ခလုတ်ကို နှိပ်ပြီး သင့်တံဆိပ်ပရင်တာကို ရွေးပါ။ ကွန်ပျူတာ၏ မူလပရင်တာကို အသုံးပြုရန် အကွက်ကို ဗလာထားပါ။',
'QZ_Step_Cert' => '4. ခွင့်ပြုချက် popup မပါဘဲ ပုံနှိပ်ရန် အောက်ပါလက်မှတ်ကို ဒေါင်းလုဒ်လုပ်ပြီး override.crt ဟု အမည်ပြောင်းကာ QZ Tray ထည့်သွင်းထားသော ဖိုင်တွဲထဲသို့ ကူးထည့်ပါ (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray)။ ထို့နောက် QZ Tray ကို ပိတ်ပြီး ပြန်စတင်ပါ။',
'QZ_Step_Test' => '5. အောက်ရှိ "Print test label" ကို နှိပ်ပါ။ QZ Tray က ခွင့်ပြုချက် တောင်းလျှင် Allow ကို နှိပ်ပါ — လက်မှတ် ထည့်သွင်းထားလျှင် ထပ်မမေးတော့ပါ။',
'QZ_Step_Save' => '6. ဤဆက်တင်များ သိမ်းရန် Submit ကို နှိပ်ပါ။ Print Barcode စာမျက်နှာမှ တံဆိပ်များကို browser ပုံနှိပ် dialog မပါဘဲ ဤပရင်တာတွင် တိုက်ရိုက် ပုံနှိပ်ပါမည်။',
'QZ_Setup_Note' => 'QZ Tray သည် သင် browse လုပ်နေသော ကွန်ပျူတာပေါ်တွင် run သောကြောင့် Stocky ကို remote ဆာဗာတွင် host ထားလျှင်ပင် အလုပ်လုပ်သည်။ တံဆိပ်ပုံနှိပ်သော ကွန်ပျူတာတိုင်းတွင် QZ Tray ထည့်သွင်းထားရန် လိုအပ်သည်။',

