'Ord_Guide_MarkPaid_Step1' => 'ဤနေရာတွင် အော်ဒါကို ဦးစွာ အတည်ပြုပါ — အတည်ပြုခြင်းက အရောင်းကို ဖန်တီးသည်။',
'Ord_Guide_MarkPaid_Step2' => 'Sales > All Sales ကို ဖွင့်ပြီး ထိုအရောင်းကို ရှာပါ (ဖောက်သည်တူပြီး အသေးစိတ် စာမျက်နှာတွင် လာရာ အွန်လိုင်းအော်ဒါကို ပြသည်)။',
