'Ord_Guide_MarkPaid_Note' => 'ဤနေရာတွင် ပြသော ငွေပေးချေမှု အခြေအနေသည် ငွေရှင်းချိန် ရွေးချယ်မှုကို ဆက်လက် မှတ်တမ်းတင်ပြီး မပြောင်းလဲပါ။ အရောင်းသည် စာရင်းကိုင် မှတ်တမ်းဖြစ်ပြီး သင့်ငွေပေးချေမှုနှင့် အမြတ် အစီရင်ခံစာများကို ထောက်ပံ့သည်။ သင်ထည့်သွင်းထားသည်ကို ပြန်စစ်ရန် သို့မဟုတ် ပြင်ရန် အရောင်းတွင် Show Payments ကို အသုံးပြုပါ။',
'Ord_Guide_Notes_Title' => 'သိထားသင့်သည်များ',
'Ord_Guide_Note_Warehouse' => 'အတည်ပြုစဉ် သင်ရွေးသော ဂိုဒေါင်က စတော့ကို မည်သည့်နေရာမှ ယူမည်ကို ဆုံးဖြတ်သည်။ အော်ဒါတစ်ခုလုံးကို မဖြည့်ဆည်းနိုင်သော ဂိုဒေါင်များကို ထိုစာရင်းတွင် Out of Stock ဟု မှတ်သားထားသည်။',
'Ord_Guide_Note_Preorder' => 'ကြိုတင်မှာယူ ပစ္စည်းများသည် စတော့စစ်ဆေးမှုကို ကျော်သောကြောင့် ၎င်းတို့ပါသော အော်ဒါကို အရေအတွက် လက်ထဲမရှိသေးလျှင်ပင် အတည်ပြုနိုင်သည်။',
