'VG_Opt_Step2' => 'Color သို့မဟုတ် Size ကဲ့သို့ ရွေးချယ်စရာအမည် ရိုက်ပါ၊ သို့မဟုတ် အကြံပြုချက်များမှ တစ်ခု ရွေးပါ။',
