'VG_Opt_Step4' => 'ဒုတိယ သို့မဟုတ် တတိယ ရွေးချယ်စရာအတွက် "Add option" ကို နှိပ်ပါ (အများဆုံး ရွေးချယ်စရာ 3 ခု)။',
'VG_Opt_Step5' => '"Generate variants" ကို နှိပ်ပါ။ ပေါင်းစပ်မှုတစ်ခုလျှင် အတန်းတစ်ခု ဖန်တီးပြီး ၎င်း၏ အမည်ကို အလိုအလျောက် တည်ဆောက်သည်၊ ဥပမာ "Red / S"။',
'VG_Opt_Step6' => 'အတန်းတစ်ခုစီတွင် ကုန်ကျစရိတ်နှင့် ဈေးနှုန်း ထည့်ပါ၊ သို့မဟုတ် "Apply to all" တွင် တန်ဖိုးရိုက်ပြီး အတန်းတိုင်းသို့ ကူးရန် Cost သို့မဟုတ် Price ကို နှိပ်ပါ။',
'VG_Opt_Step7' => 'ကုဒ်များကို သင့်အတွက် ထုတ်ပေးသည်။ သင့်ကိုယ်ပိုင်ကုဒ် ရိုက်ပါ သို့မဟုတ် နောက်တစ်ခု ထုတ်ရန် refresh icon ကို နှိပ်ပါ။',
