'VG_List_Text' => 'အတန်းတစ်ခု ထပ်ထည့်ရန် variant အမည် ရိုက်ပြီး Enter နှိပ်ပါ (သို့မဟုတ် Add ကို နှိပ်ပါ)၊ ထို့နောက် ၎င်း၏ ကုဒ်နှင့် ဈေးနှုန်းများ ဖြည့်ပါ။ ဤသည်မှာ ဂန္တဝင် အပြုအမူဖြစ်ပြီး ရှိပြီးသား ကုန်ပစ္စည်းများအတွက် ဆက်လက် ရရှိနိုင်သည်။',
