'Upd_Guide_Run_Validation' => 'အပ်လုဒ်ပြီးနောက် {auto} ({button} ခလုတ်ဖြင့် ပြန် run နိုင်သည်)။ စနစ်က စစ်ဆေးသည်များ: ZIP ခိုင်မာမှု၊ package ဖွဲ့စည်းပုံနှင့် ပြည့်စုံမှု၊ ဗားရှင်း ကိုက်ညီမှု (downgrade ကို ငြင်းပယ်သည်)၊ လိုအပ်သော PHP ဗားရှင်းနှင့် extension များ၊ ဖိုင် ခွင့်ပြုချက်များ၊ disk နေရာလွတ်၊ ဒေတာဘေ့စ် ချိတ်ဆက်မှု၊ configuration နှင့် အခြား update မ run နေကြောင်း။',
'Upd_Validation_Runs_Automatically' => 'စစ်ဆေးမှုသည် အလိုအလျောက် run သည်',
'Upd_Guide_Run_Review' => '{panel} panel ကို ပြန်စစ်ပါ။ အရေးကြီးသော စစ်ဆေးမှုတိုင်း အောင်မြင်မှသာ {button} ခလုတ် ပေါ်လာသည်။ စစ်ဆေးမှုတစ်ခု မအောင်မြင်လျှင် မက်ဆေ့ချ်က မည်သည့်အရာကို ပြင်ရမည်ကို အတိအကျ ပြောပြသည်။',
'Upd_Guide_Run_Click' => '{button} ကို နှိပ်ပြီး အတည်ပြုပါ။ ထို့နောက် {keep} — တိုးတက်မှု rail ကို စောင့်ကြည့်ရုံသာ။ စနစ်က အစဉ်လိုက် လုပ်ဆောင်သည်:',
'Upd_Keep_Page_Open' => 'ဤစာမျက်နှာကို ဖွင့်ထားပါ',
'Upd_Guide_Phase_Backup' => '{label} — ဒေတာဘေ့စ် dump အပြည့်အစုံ၊ update က ပြောင်းလဲနိုင်သော application ဖိုင်တိုင်း၏ ZIP နှင့် {env} ၏ မိတ္တူကို ဖန်တီးပြီး {verified}။ သင့်အပ်လုဒ်များ ({images}) နှင့် {storage} ကို update က ဘယ်တော့မှ မထိသောကြောင့် archive မလုပ်ပါ။ Backup ဖန်တီး၍ မရလျှင် update သည် ဤနေရာတွင် ရပ်ပြီး ဘာမှ မပြောင်းလဲပါ။',
'Upd_Verified' => 'စစ်ဆေးအတည်ပြုသည်',
'Upd_Guide_Phase_Prepare' => '{label} — ဗားရှင်းအသစ်ကို staging နေရာသို့ ဖြည်ပြီး ထပ်မံ စစ်ဆေးသည်။ လက်ရှိ application ကို မထိရသေးပါ။',
'Upd_Guide_Phase_Maintenance' => '{label} — maintenance mode ကို ဖွင့်သည်; ဧည့်သည်များသည် ဖော်ရွေသော "ခဏနေ ပြန်လာပါမည်" မျက်နှာပြင်ကို မြင်ရသည်။',
'Upd_Guide_Phase_Files' => '{label} — ဖိုင်အသစ်များကို ချက်ချင်းနီးပါး အစားထိုးသည်; ဖိုင်ဟောင်းများကို ပြန်လှန်ရန်အတွက် သီးခြားထားသည်။ ကာကွယ်ထားသော path များ ({env}၊ {storage}၊ {images}) ကို ဘယ်တော့မှ အစားမထိုးပါ။',
'Upd_Guide_Phase_Database' => '{label} — migration များ run ပြီး ခွင့်ပြုချက်၊ ဘာသာပြန်နှင့် ပုံစံများကို ပြန်လည်ဆန်းသစ်သည်။',
'Upd_Guide_Phase_Cache' => '{label} — cache အားလုံးကို ရှင်းလင်းပြီး ပြန်တည်ဆောက်သည်။',
'Upd_Guide_Phase_Verify' => '{label} — ကျန်းမာရေး စစ်ဆေးမှုများက ဗားရှင်းအသစ် စတင်နိုင်ကြောင်း၊ ဒေတာဘေ့စ် အလုပ်လုပ်ကြောင်း၊ migration အားလုံး run ပြီးကြောင်းနှင့် configuration မှန်ကန်ကြောင်း အတည်ပြုသည်။',
'Upd_Guide_Phase_Done' => '{label} — maintenance mode ကို ဖယ်ရှားပြီး ယာယီဖိုင်များကို ရှင်းလင်းသည်။',
'Upd_Guide_Run_Success' => '{success} ကို မြင်သည့်အခါ admin panel asset အသစ်များ ဖွင့်နိုင်ရန် {reload} ကို နှိပ်ပြီး browser ကို hard-refresh ({keys}) လုပ်ပါ။',
'Upd_Update_Successful_Short' => 'Update အောင်မြင်ပါသည်',
'Upd_Guide_No_Internet' => 'Update လုပ်နေစဉ် အင်တာနက် ချိတ်ဆက်မှု မလိုအပ်ပါ — အားလုံး အပ်လုဒ်လုပ်ထားသော ZIP မှ လာသည်။ ချိတ်ဆက်မှု ပြတ်ခြင်း သို့မဟုတ် browser ပိတ်ခြင်းသည် update ကို မပျက်စီးစေပါ: ဆာဗာက ရပ်သွားသည့်နေရာကို အတိအကျ မှတ်ထားသည်။',
'Upd_Guide_Wrong_Title' => '3. တစ်ခုခု မှားယွင်းလျှင်',
'Upd_Guide_Wrong_Rollback' => '{label} — ဖိုင်များ ပြောင်းလဲစပြီးနောက် တစ်ခုခု မအောင်မြင်လျှင် (ဖြည်ခြင်း အမှား၊ migration မအောင်မြင်ခြင်း၊ ကျန်းမာရေး စစ်ဆေးမှု မအောင်မြင်ခြင်း၊ disk ပြည့်ခြင်း၊ …) စနစ်က စစ်ဆေးအတည်ပြုထားသော backup မှ ယခင်ဖိုင်များနှင့် ဒေတာဘေ့စ်ကို အလိုအလျောက် ပြန်လည်ရယူပြီး maintenance mode ကို ဖယ်ရှားကာ {message} ဟု သတင်းပို့သည်။ သင် စတင်ခဲ့သည့်နေရာသို့ အတိအကျ ပြန်ရောက်မည်။',
