'Upd_Guide_Wrong_Interrupted' => '{label} (ဆာဗာ ပြန်စခြင်း၊ အချိန်ကုန်ခြင်း၊ browser ပိတ်ခြင်း၊ လျှပ်စစ်ပြတ်ခြင်း) — ဤစာမျက်နှာကို ပြန်ဖွင့်သည့်အခါ အနီရောင် banner က ဘေးကင်းသော ရွေးချယ်မှု နှစ်ခု ပေးသည်: {resume} (ရပ်သွားသည့် အဆင့်အတိအကျမှ ဆက်လုပ်သည်) သို့မဟုတ် {rollback} (backup မှ ယခင်ဗားရှင်းကို ပြန်လည်ရယူသည်)။',
