'Upd_Before' => 'မတိုင်မီ',
'Upd_Guide_Backups_Panel' => '{tab} tab ရှိ {panel} panel တွင် ၎င်းတို့ကို ရက်စွဲ၊ ဗားရှင်းနှင့် အရွယ်အစားဖြင့် စာရင်းပြသည်။ ထိုနေရာမှ backup အပြည့်အစုံ မည်သည့်တစ်ခုကိုမဆို {restore} နိုင်သည် (ဖိုင်များ + ဒေတာဘေ့စ် — လက်ရှိဒေတာဘေ့စ်၏ ဘေးကင်းရေး မိတ္တူကို ဦးစွာ ယူသည်) သို့မဟုတ် အဟောင်းများကို {delete} နိုင်သည်။',
'Upd_Restore_Verb' => 'ပြန်လည်ရယူ',
'Upd_Delete_Verb' => 'ဖျက်',
'Upd_Guide_Backups_Retention' => 'Backup မည်မျှ ထိန်းထားမည်ကို ရွေးရန် {keep} ကို အသုံးပြုပါ; update အောင်မြင်ပြီးတိုင်း အဟောင်းများကို အလိုအလျောက် ဖယ်ရှားသည်။ ကျန်ရှိသော တစ်ခုတည်းသော backup အပြည့်အစုံကို ဘယ်တော့မှ ဖျက်၍ မရပါ — ပြန်လှန်နိုင်သော နည်းလမ်း အမြဲရှိနေမည်။',
'Upd_Guide_Manual_Title' => '5. ကိုယ်တိုင် update လုပ်ခြင်း (အရန်နည်းလမ်း)',
'Upd_Guide_Manual_Text' => 'ကိုယ်တိုင် update လုပ်လိုလျှင် သို့မဟုတ် သင့်ဆာဗာတွင် uploader ကို အသုံးမပြုနိုင်လျှင် ဤစာမျက်နှာ၏ {tab} tab ရှိ အဆင့်ဆင့် ညွှန်ကြားချက်များကို လိုက်နာပါ။',
'Upd_Guide_Clear_Cache_First' => 'မည်သည့် update ပြီးနောက်မဆို စာမျက်နှာများ ပျက်နေ သို့မဟုတ် ဗလာဖြစ်နေလျှင် browser cache ကို ဦးစွာ ရှင်းလင်းပါ — အများအားဖြင့် ၎င်းသည် အကြောင်းရင်း ဖြစ်သည်။',
'Upd_Restore_Backup_Confirm' => 'ဤ backup ကို ပြန်လည်ရယူမလား? လက်ရှိဖိုင်များနှင့် လက်ရှိဒေတာဘေ့စ်ကို backup ဖြင့် အစားထိုးပါမည်။ လက်ရှိဒေတာဘေ့စ်၏ ဘေးကင်းရေး မိတ္တူကို ဦးစွာ ယူပါမည်။ (v{version} — {date})',
'Woo_Guide_Lead' => 'WooCommerce ဆိုင်တစ်ခုသည် ERP နှင့် မည်သို့ ကိုက်ညီအောင် ထိန်းထားသည်။ အောက်ပါ cron လိုင်းများကို ဤဆာဗာအတွက် တည်ဆောက်ထားသောကြောင့် ၎င်းပေါ်သို့ တိုက်ရိုက် ကူးထည့်နိုင်သည်။',
'Woo_Guide_Ways_Note' => 'Shopify နှင့် မတူဘဲ WooCommerce သည် ERP သို့ ကိုယ်တိုင် ဘာမှ မပို့ပါ — ဤနေရာတွင် webhook လက်ခံကိရိယာ မရှိသောကြောင့် {in} ဒေတာအားလုံးသည် အချိန်ဇယားအတိုင်း ရောက်သည်။ {out} စတော့သာ ချက်ချင်း ဖြစ်နိုင်သည်။',
