'Woo_Not_Configured_Yet' => 'မသတ်မှတ်ရသေး',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress application password (ရွေးချယ်နိုင်)',
'Woo_Guide_Wp_App_Password_Text' => 'ကုန်ပစ္စည်းပုံများအတွက်သာ အသုံးပြုသည်။ WooCommerce API သည် ကုန်ပစ္စည်း၊ စတော့၊ အမျိုးအစား၊ တံဆိပ်အမှတ်တံဆိပ်၊ ဖောက်သည်နှင့် အော်ဒါများကို ရွှေ့ပြောင်းသည်; WordPress API သည် Media Library ကို ရှာဖွေပြီး မရှိသေးသော ပုံကို အပ်လုဒ်လုပ်သည်။',
'Woo_Guide_Wp_App_Password_Note' => 'Media ကို စီမံနိုင်သော WordPress အသုံးပြုသူကို အသုံးပြုပြီး {path} အောက်တွင် password ဖန်တီးပါ။ Field နှစ်ခုစလုံး ဗလာထားလျှင်လည်း အားလုံး sync ဆက်လုပ်သည် — ပုံ ပူးတွဲခြင်းကိုသာ ကျော်သည်။',
'Woo_Guide_Pick_Way_Title' => 'ထို့နောက် ကိုက်ညီအောင် ထိန်းမည့်နည်းကို ရွေးပါ',
'Woo_Right_Away' => 'ချက်ချင်း',
'Woo_Stock_Live' => 'စတော့ တိုက်ရိုက်',
'Woo_Stock_Not_Live' => 'စတော့ တိုက်ရိုက် မဟုတ်',
'Woo_Guide_Realtime_Lead' => 'တစ်ဖက်တည်းသာ: ERP မှ ထွက်သွားသော စတော့နှင့် ကုန်ပစ္စည်းများ။ WooCommerce တွင် ပြုလုပ်သော အော်ဒါများနှင့် ကုန်ပစ္စည်း ပြင်ဆင်မှုများသည် အချိန်ဇယားအတိုင်းသာ ရောက်သည် — အခြား tab ကို ကြည့်ပါ။',
'Woo_Push_Stock_On_Change' => 'စတော့ ပြောင်းလဲသည်နှင့် ချက်ချင်း push လုပ်ရန်',
'Woo_Setting_People_Miss' => 'လူအများ လွတ်သွားတတ်သော ဆက်တင်',
'Woo_Guide_Pos_Sale_Not_Reach' => 'POS အရောင်းသည် WooCommerce သို့ အလိုအလျောက် {not}။ ပိတ်ထားလျှင် ဆိုင်သည် နောက်တစ်ကြိမ် စတော့ sync — မူလအားဖြင့် တစ်နာရီ — မှသာ သိရှိမည်ဖြစ်ပြီး ထိုကာလအတွင်း ကောင်တာတွင် ရောင်းပြီးသား ယူနစ်တစ်ခုကို ရောင်းမိနိုင်သည်။',
'Woo_Does_Not' => 'မရောက်ပါ',
'Woo_Guide_Tick_Instant' => '{settings} tab တွင် {option} ကို အမှန်ခြစ်ပါ။ စနစ်ထည့်သွင်းမှု အားလုံး ဤမျှသာ — worker မလို၊ cron မလို။ ထို့နောက် အရောင်း၊ ပြန်အပ်မှု၊ ချိန်ညှိမှု၊ လွှဲပြောင်းမှုနှင့် လက်ခံရရှိသော ဝယ်ယူမှုတိုင်းသည် အရောင်း သိမ်းပြီးသည်နှင့် ထိုကုန်ပစ္စည်းများကိုသာ push ပို့ပြီး လိုင်းနှစ်ဆယ်ပါ အရောင်းတစ်ခုသည် push နှစ်ဆယ်မဟုတ်ဘဲ တစ်ခုသာ ကုန်ကျသည်။ ကောင်တာက ၎င်းကို ဘယ်တော့မှ မစောင့်ပါ။',
'Woo_Currently' => 'လက်ရှိ:',
'Woo_Instant_On_Text' => 'ဖွင့် — ပြောင်းလဲသည့်အခါ စတော့ push လုပ်သည်',
'Woo_Instant_Off_Text' => 'ပိတ် — အချိန်ဇယားအတိုင်းသာ စတော့',
'Woo_Guide_Instant_Note' => 'WooCommerce နှင့် ချိတ်ဆက်ပြီးသား ကုန်ပစ္စည်းများကိုသာ push လုပ်သည် — sync မလုပ်ဖူးသော ကုန်ပစ္စည်းသည် ဆိုင်တွင် ပြင်စရာ မရှိပါ။ Variable ကုန်ပစ္စည်းများသည် ၎င်းတို့၏ မိခင်မှတစ်ဆင့် သွားပြီး combo ကို ၎င်း၏ အစိတ်အပိုင်း တစ်ခုခု လှုပ်ရှားသည့်အခါ ပြန် push လုပ်သည်။ အစုလိုက် လုပ်ဆောင်ချက်များ (ကုန်ပစ္စည်း ဖျက်ခြင်း၊ ဂိုဒေါင် ပြန်သတ်မှတ်ခြင်း) သည် event မဖြစ်စေဘဲ စတော့ရေးသောကြောင့် နာရီအလိုက် စတော့ sync ကိုလည်း ထားသင့်သည့် အကြောင်းရင်းတစ်ခု ဖြစ်သည်။',
'Woo_Push_Products_On_Save' => 'ကုန်ပစ္စည်းများ သိမ်းဆည်းသည်နှင့် ချက်ချင်း push လုပ်ရန်',
'Woo_Guide_Tick_Auto_Products' => '{settings} tab တွင် {option} ကို အမှန်ခြစ်ပါက Stocky တွင် ဖန်တီး၊ ပြင်ဆင် သို့မဟုတ် ပွားထားသော ကုန်ပစ္စည်းကို သိမ်းပြီးသည်နှင့် WooCommerce သို့ ပို့သည် — အသေးစိတ်၊ ဈေးနှုန်း၊ variant များနှင့် ပုံများ၊ ထို့နောက် ၎င်း၏ စတော့။ ကုန်ပစ္စည်းအသစ်ကို ညစဉ် ကုန်ပစ္စည်း sync ကို စောင့်မည့်အစား ဆိုင်တွင် ချက်ချင်း ဖန်တီးသည်။',
'Woo_On' => 'ဖွင့်',
'Woo_Off' => 'ပိတ်',
'Woo_Guide_Bulk_Imports_Note' => 'အစုလိုက် import များကို တစ်ခုချင်း push မလုပ်ပါ — import ပြီးနောက် ကုန်ပစ္စည်း sync run ပါ။ Push လုပ်သော ကုန်ပစ္စည်း မှန်ကန်သော အမျိုးအစားထဲ ရောက်စေရန် အမျိုးအစားနှင့် တံဆိပ်အမှတ်တံဆိပ်များကို ဦးစွာ sync လုပ်ပါ။',
'Woo_Nothing_Else_To_Install' => 'ထပ်ထည့်သွင်းစရာ မရှိပါ',
'Woo_Guide_Same_Process' => 'Queue worker မလို၊ cron entry မလို။ Push သည် အရောင်းကို ဆောင်ရွက်ပေးသော process တစ်ခုတည်းတွင် response ပြန်ပို့ {after} run သောကြောင့် ကောင်တာသည် WooCommerce ကို ဘယ်တော့မှ မစောင့်ရပါ။ Push များ ဘယ်တော့မှ မထပ်ပါ: တစ်ခု run နေစဉ် ပြုလုပ်သော ပြောင်းလဲမှုများသည် ၎င်းကို စောင့်ပြီး ချက်ချင်း နောက်မှ ထွက်သွားသည်။',
'Woo_After' => 'ပြီးနောက်မှ',
'Woo_Guide_Shop_Stops_Answering' => 'ဆိုင်က မတုံ့ပြန်တော့လျှင် ရှစ်စက္ကန့်ပြီးနောက် စွန့်လွှတ်ပြီး အရောင်းတိုင်း ၎င်းကို ထပ်မစောင့်ရစေရန် push များကို ငါးမိနစ် ခဏရပ်သည်; ထိုအတောအတွင်း ဝင်လာသော ပြောင်းလဲမှုများသည် ခဏရပ်ပြီးနောက် ပထမ push နှင့်အတူ ထွက်သွားပြီး နာရီအလိုက် စတော့ sync က မည်သို့ပင်ဖြစ်စေ လိုက်မီစေသည်။ ခဏရပ်မှုတိုင်းကို Logs tab တွင် မှတ်တမ်းတင်သည်။',
'Woo_Guide_Artisan_Exception' => 'ခြွင်းချက်တစ်ခု: artisan command က ပြုလုပ်သော စတော့ပြောင်းလဲမှုတွင် နောက်မှလိုက်ရမည့် response မရှိသောကြောင့် ၎င်းကို {queue} ပေါ်တွင် တန်းစီထားသည်။ ၎င်းတို့ကိုလည်း မြန်မြန် ထွက်သွားစေရန် ထို queue ကို ရှင်းထုတ်ပါ:',
'Woo_Cron_Line_Copied' => 'Cron လိုင်း ကူးယူပြီး',
'Woo_Command_Copied' => 'Command ကူးယူပြီး',
'Woo_Guide_Not_Woo_Queue' => '{queue} queue ကို တမင် မသုံးပါ: ၎င်းသည် နာရီပေါင်းများစွာ ကြာသော ကတ်တလောက် batch များကို သယ်ဆောင်ပြီး ၎င်း၏နောက်တွင် တန်းစီထားသော ချက်ချင်း push သည် ချက်ချင်း ဖြစ်မည်မဟုတ်ပါ။',
'Woo_On_A_Schedule' => 'အချိန်ဇယားအတိုင်း',
'Woo_Guide_Scheduled_Lead' => 'အားလုံးကို အခါအားလျော်စွာ နှစ်ဖက်စလုံး ပြန်စစ်သည်။ ဤနည်းဖြင့် အော်ဒါများ ERP သို့ ရောက်သည်၊ ကတ်တလောက် ထုတ်ဝေသည်၊ အမြန်လမ်းကြောင်း လွတ်သွားသမျှကို ပြင်ပေးသည်။ Job တစ်ခုစီတွင် ကိုယ်ပိုင် cron entry ရှိသောကြောင့် သင်လိုသည်ကိုသာ run နိုင်သည်။',
'Woo_Guide_Sync_Drains_Queue' => '{command} သည် run နေစဉ် ၎င်း၏ ကိုယ်ပိုင် queue ကို ရှင်းထုတ်သောကြောင့် ဤလိုင်းများအတွက် သီးခြား worker မလိုပါ။ Windows တွင် program {program} နှင့် argument များ အတူတူဖြင့် Task Scheduler ကို အသုံးပြုပြီး {path} တွင် စတင်ပါ။',
'Woo_Or_No_Cron' => 'သို့မဟုတ် cron လုံးဝ မသုံးပါ',
'Woo_Guide_No_Cron_Text' => 'ဤနေရာရှိ tab တိုင်းသည် လိုအပ်သလို sync လုပ်ပြီး ကိုယ်တိုင် sync သည် စာမျက်နှာ ဖွင့်ထားစဉ် ၎င်း၏ batch များကို ရှင်းထုတ်သည် — ထို့ကြောင့် ဆိုင်ငယ်တစ်ခုသည် cron entry လုံးဝမပါဘဲ run နိုင်သည်။ ဆုံးရှုံးသည်မှာ မည်သူမျှ မကြည့်နေစဉ် ဖြစ်ပျက်သမျှ ဖြစ်သည်: တစ်ယောက်ယောက် ခလုတ်နှိပ်မှသာ အော်ဒါများ ရောက်လာသည်။',
'Woo_Commands_Worth_Knowing' => 'သိထားသင့်သော command များ',
