'Telegram_G_B_Body' => 'မက်ဆေ့ချ် နှစ်မျိုးသည် Telegram ၏ ကိုယ်ပိုင် queue တွင် စောင့်ဆိုင်းသည်: ပို့ခြင်း မအောင်မြင်သည့်အရာ (Telegram ကို ခဏ ဆက်သွယ်မရ) ကို နောက်မိနစ်အနည်းငယ်အတွင်း နောက်ထပ် သုံးကြိမ်အထိ ပြန်ကြိုးစားသည်၊ နှင့် admin ပြင်ပတွင် ဖြစ်ပေါ်သော ဖြစ်ရပ်များ — WooCommerce သို့မဟုတ် Shopify မှ တင်သွင်းသော အော်ဒါများ၊ artisan command များ။ ဤ cron entry က ၎င်းတို့ကိုသာ ပို့ပေးသည်:',
