'Presta_Push_Products_Desc' => 'PrestaShop တွင် မရှိသေးသော ရိုးရိုး ကုန်ပစ္စည်းများကို (၎င်းတို့၏ လက်ရှိ စတော့ဖြင့်) ဖန်တီးသည်။ ချိတ်ပြီးသား ကုန်ပစ္စည်းများနှင့် မျိုးကွဲ ကုန်ပစ္စည်းများကို ကျော်သည် — ကုန်ပစ္စည်း အသေးစိတ်များကို PrestaShop တွင် ဆက်ပြင်ပါ၊ သို့မဟုတ် local မိတ္တူကို refresh လုပ်ရန် ဆွဲယူပါ။',
'Presta_Pull_Products_Desc' => 'PrestaShop ကုန်ပစ္စည်းများကို တင်သွင်းပြီး ရှိပြီးသားများကို reference (SKU) ဖြင့် ကိုက်ညီစေကာ ကျန်သည်များကို ဖန်တီးသည်။ Combination များကို ၎င်းတို့၏ မိခင် ကုန်ပစ္စည်းအဖြစ် တင်သွင်းသည်။',
'Presta_Reset_Product_Confirm' => 'ကုန်ပစ္စည်း ချိတ်ဆက်မှုများကို ပြန်သတ်မှတ်မလား? အော်ဒါ မှတ်တမ်းသည် ၎င်း၏ ချိတ်ဆက်မှုများကို ဆက်ထားမည်။',
'Presta_Push_Stock_Desc' => 'ချိတ်ထားသော ကုန်ပစ္စည်းတိုင်းအတွက် shop ၏ စတော့ (stock_availables) ကို အပ်ဒိတ်လုပ်သည်။',
