'Presta_Guide_5' => 'အရေအတွက် ပြောင်းလဲတိုင်း စတော့ကို ပို့ပြီး အော်ဒါများကို ပုံမှန် ဆွဲယူပါ — PrestaShop တွင် webhook မရှိသဖြင့် သင် ဆွဲယူမှသာ အော်ဒါများ ရောက်လာသည်။',
