'Jumia_Push_Prices_Stock_Desc' => 'Jumia listing ၏ {sku} နှင့် ကိုက်ညီသော SKU ရှိသည့် ကုန်ပစ္စည်း (နှင့် မျိုးကွဲ) တိုင်းအတွက် လက်ရှိ စျေးနှုန်းနှင့် အရေအတွက်ကို ပို့သည်။ အပ်ဒိတ်များကို Seller Center feed များအဖြစ် တင်သွင်းပြီး asynchronous အဖြစ် အသုံးချသည် — feed ID ကို Logs tab တွင် မှတ်တမ်းတင်ပြီး ပစ္စည်းအလိုက် ငြင်းပယ်ချက်များသည် Seller Center ၏ feed status မျက်နှာပြင်တွင် ပေါ်လာသည်။',
