'Jumia_Pull_Orders_Desc' => 'Marketplace အော်ဒါများကို အရောင်းများအဖြစ် ({ref} ကဲ့သို့ ရည်ညွှန်းချက်များ) Seller SKU ဖြင့် သင့်ကုန်ပစ္စည်းများနှင့် ကိုက်ညီစေ၍ တင်သွင်းသည်။ တင်သွင်းပြီးသားနှင့် ပယ်ဖျက်ထားသော အော်ဒါများကို ကျော်သဖြင့် ပုံမှန် ဆွဲယူခြင်းသည် ဘေးကင်းသည်။ ပို့ဆောင်ပြီး အော်ဒါများအတွက်သာ ငွေပေးချေမှုကို ငွေချေပြီးဟု မှတ်သည် (Jumia သည် COD အများစု ဖြစ်သည်)။',
'Jumia_Guide_1' => 'Jumia {sellerCenter} တွင် {menu} ကို ဖွင့်ပြီး API key တစ်ခု ထုတ်ပါ။',
'Jumia_Guide_2' => 'သင့်နိုင်ငံ၏ API URL (ဥပမာ Nigeria အတွက် {ng}၊ Kenya အတွက် {ke}၊ Egypt အတွက် {eg})၊ သင့် Seller Center အကောင့် အီးမေးလ်နှင့် key ကို ထည့်ပါ — ထို့နောက် {test} ကို run ပါ။',
'Jumia_Guide_3' => 'Jumia listing တစ်ခုစီ၏ {sku} သည် Stocky ကုန်ပစ္စည်းကုဒ်နှင့် တူညီကြောင်း သေချာပါစေ — ၎င်းသည် စတော့ ပို့ခြင်းနှင့် အော်ဒါ ကိုက်ညီစေခြင်း နှစ်ခုလုံးအတွက် သုံးသော သတ်မှတ်ချက် ဖြစ်သည်။',
