'Shopify_G_Lead_Generic' => 'Shopify shop တစ်ခုသည် ERP နှင့် မည်သို့ တပြိုင်နက်တည်း ရှိနေသနည်း။ ၎င်း၏ ကိုယ်ပိုင် အခြေအနေကို ကြည့်ရန် အထက်တွင် စတိုးတစ်ခု ရွေးပါ၊ သို့မဟုတ် ဒီအတိုင်း ဖတ်ပါ — cron line နှင့် webhook URL သည် မည်သည့်စတိုးကို ချိတ်ဆက်သည်ဖြစ်စေ တူညီသည်။',
'Shopify_G_Ways_Note' => 'Shop အများစုသည် နှစ်ခုလုံးကို run ကြသည်: ပထမတစ်ခုက shop ကို မိနစ်အလိုက် နောက်ဆုံးအခြေအနေ ဖြစ်စေပြီး ဒုတိယတစ်ခုက ပထမ လွတ်သွားသည်များကို ဖမ်းယူသည် — ဘယ်တော့မှ မရောက်လာသော webhook၊ Shopify admin တွင် တိုက်ရိုက် ပြင်ဆင်မှု၊ site ပျက်နေသော ညတစ်ည။',
'Shopify_G_Both_Need' => 'နှစ်ဖက်စလုံး ဤအရာကို ဦးစွာ လိုအပ်သည်',
'Shopify_G_Credentials' => 'Shopify အထောက်အထားများ',
'Shopify_G_Cred_Intro' => 'January 2026 မှစ၍ Shopify သည် admin အတွင်း custom app များကို မဖန်တီးတော့သဖြင့် ချိတ်ဆက်မှု နှစ်မျိုး ရှိသည်:',
'Shopify_G_Cred_DevDash' => '{app} (ယခု ချိတ်ဆက်သော shop မည်သည့်ခုမဆို) — {path}။ ဤစတိုး sync လုပ်သည့်အရာအတွက် Admin API scope များကို ခွင့်ပြုပြီး app ကို shop တွင် install လုပ်ကာ app ၏ Settings စာမျက်နှာမှ {clientId} နှင့် {clientSecret} ကို {where} ထဲ ကူးယူပါ။ ERP သည် ၎င်းတို့ကို access token အဖြစ် ကိုယ်တိုင် လဲလှယ်ပြီး 24 နာရီတိုင်း သက်တမ်းမကုန်မီ သက်တမ်းတိုးသည်။ Client secret က webhook များကိုလည်း sign လုပ်သဖြင့် ထပ်မံ ဘာမှ မလိုပါ။ App နှင့် shop သည် တူညီသော Shopify organisation တွင် ရှိရမည်။',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard အက်ပ်',
'Shopify_G_Cred_Legacy' => '{app} (2026 မတိုင်မီ admin တွင် ဖန်တီးခဲ့သည်) — ၎င်း၏ {token} ({prefix}) နှင့် ၎င်း၏ {secret} ကို webhook signing secret အဖြစ် ထားလျက် ပြောင်းလဲမှုမရှိဘဲ ဆက်အလုပ်လုပ်သည်။ Token နှင့် တန်ဖိုး မတူပါ၊ ၎င်းတို့ကို ပြောင်းပြန် ထည့်မိခြင်းသည် webhook များ ငြင်းပယ်ခံရသည့် အဖြစ်များသော အကြောင်းရင်း ဖြစ်သည်။',
'Shopify_G_Legacy_App' => 'ယခင် စိတ်ကြိုက်အက်ပ်',
'Shopify_G_API_Secret_Key' => 'API လျှို့ဝှက်ကီး',
'Shopify_G_Stored' => 'သိမ်းထားသည်',
'Shopify_G_Missing_Refused' => 'မရှိ — ပို့မှုများကို ငြင်းပယ်မည်',
'Shopify_G_Where_Data_Desc' => '{path} ဤ shop ရောင်းချသော စတော့ပိုင် ERP ဂိုဒေါင်နှင့် ထိုစတော့ကို ရေးသွင်းမည့် Shopify location။ ၎င်းတို့မပါဘဲ inventory sync နှင့် အော်ဒါ တင်သွင်းမှု နှစ်ခုလုံး လုပ်ဆောင်ရန် ငြင်းပယ်သည်။',
'Shopify_G_Currently' => 'လက်ရှိ: ဂိုဒေါင် {warehouse}၊ location {location}',
'Shopify_G_Not_Set_Lower' => 'မသတ်မှတ်ရသေး',
'Shopify_G_Ready' => 'အသင့်',
'Shopify_G_Incomplete' => 'မပြည့်စုံ',
'Shopify_G_Manual_Syncs' => 'ကိုယ်တိုင် စတင်သော sync များ',
'Shopify_G_Manual_Desc' => '{centre} မှ စတင်သော sync သည် ချက်ချင်း တုံ့ပြန်ပြီး နောက်ခံတွင် အပိုင်းတိုလေးများဖြင့် လုပ်ဆောင်သည်၊ အပိုင်းတစ်ခုစီသည် ယခင်တစ်ခု ရပ်ခဲ့သည့်နေရာမှ ဆက်လုပ်သည်။ ကြာရှည်သော web request များကို ဖြတ်တောက်သော hosting (LiteSpeed, nginx, load balancer) ကြောင့် catalog ကြီးကို တစ်ဝက်တစ်ပျက် ဘယ်တော့မှ မဖြတ်တောက်ခံရဘဲ စာမျက်နှာ ပိတ်လိုက်ခြင်းကလည်း ၎င်းကို မရပ်စေပါ။ ၎င်းအတွက် worker သည် နောက်ထပ် cron line တစ်ကြောင်း ဖြစ်သည်:',
'Shopify_G_Cron_Copied' => 'Cron လိုင်း ကူးယူပြီး',
'Shopify_G_Manual_Note' => '၎င်းမပါဘဲလည်း sync ပြီးဆုံးနိုင်သော်လည်း Sync Centre စာမျက်နှာ ဖွင့်ထားစဉ်သာ ဖြစ်သည်: worker က run ကို စက္ကန့်အနည်းငယ်အတွင်း မယူပါက စာမျက်နှာက ကိုယ်တိုင် တစ်ကြိမ်လျှင် request တိုတစ်ခုဖြင့် ဆက်လုပ်သည်။ Windows တွင် Task Scheduler ကို မိနစ်တိုင်း သုံးပါ: program {program}၊ arguments {args}၊ started in {dir}။',
'Shopify_G_Then_Pick' => 'ထို့နောက် ကိုက်ညီအောင် ထိန်းမည့်နည်းကို ရွေးပါ',
'Shopify_G_Right_Away' => 'ချက်ချင်း',
'Shopify_G_Stock_Live' => 'စတော့ တိုက်ရိုက်',
'Shopify_G_Stock_Not_Live' => 'စတော့ တိုက်ရိုက် မဟုတ်',
'Shopify_G_Realtime_Lead' => 'ပြောင်းလဲမှုတစ်ခုစီကို ဖြစ်ပေါ်သည်နှင့် စက္ကန့်ပိုင်းအတွင်း ပို့သည်။ အပိုင်း နှစ်ခုရှိပြီး ၎င်းတို့သည် သီးခြား switch များ ဖြစ်သည်: {webhooks} က shop ၏ ကိုယ်ပိုင် ဖြစ်ရပ်များကို ယူလာပြီး {push} က စတော့ကို ပို့ထုတ်သည်။',
'Shopify_G_Webhooks_Lower' => 'webhook များ',
'Shopify_G_Instant_Push_Lower' => 'ချက်ချင်း စတော့ ပို့ခြင်း',
'Shopify_G_Webhooks_In' => 'Webhook များ — ဆိုင် → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify တွင် ပြုလုပ်သော အော်ဒါများ၊ အော်ဒါ အခြေအနေ ပြောင်းလဲမှုများနှင့် ကုန်ပစ္စည်း၊ ဖောက်သည်နှင့် စတော့ ပြင်ဆင်မှုများ။ စတိုးကို ဖွင့်ပြီး ၎င်း၏ {tab} ပေါ်ရှိ {button} ကို နှိပ်ပါ — နှစ်ကြိမ် နှိပ်လည်း ဘေးကင်းသည်။ Shopify က ဤနေရာသို့ ပို့သည်:',
'Shopify_G_Webhooks_Tab' => 'Webhook များ တက်ဘ်',
'Shopify_G_Webhooks_Note' => 'လိပ်စာကို အင်တာနက်မှ HTTPS ဖြင့် ဆက်သွယ်နိုင်ရမည် — Shopify သည် {localhost} သို့မဟုတ် {test} domain သို့ မပို့ပါ။ ပို့မှုတစ်ခုစီကို တစ်ကြိမ်သာ မှတ်တမ်းတင်သဖြင့် Shopify ၏ ပြန်ကြိုးစားမှုများက အော်ဒါ ထပ်မဖန်တီးနိုင်ဘဲ မအောင်မြင်သည့်တစ်ခုကို ပြန်ဖွင့်နိုင်သည်။ အဆင့် 1 မှ signing secret ကို မသိမ်းမချင်း ပို့မှုများကို ငြင်းပယ်သည်။',
'Shopify_G_Instant_Out' => 'ချက်ချင်း စတော့ ပို့ခြင်း — ERP → ဆိုင်',
'Shopify_G_Setting_Missed' => 'လူအများ လွတ်သွားတတ်သော ဆက်တင်',
'Shopify_G_Pos_Not_Auto' => 'POS အရောင်းသည် Shopify သို့ အလိုအလျောက် {not}ရောက်ပါ။ ပိတ်ထားပါက shop သည် နောက် Inventory push အဆင့်တွင်သာ သိရှိမည် — ထိုကြားကာလအတွင်း ငွေရှင်းကောင်တာတွင် ရောင်းပြီးသား ယူနစ်ကို ရောင်းမိနိုင်သည်။',
'Shopify_G_Not' => 'မ',
