'Shopify_G_This_Store' => 'ဤစတိုး:',
'Shopify_G_Push_On' => 'ဖွင့် — ပြောင်းလဲသည့်အခါ စတော့ push လုပ်သည်',
'Shopify_G_Push_Off' => 'ပိတ် — အချိန်ဇယားအတိုင်းသာ စတော့',
'Shopify_G_Push_Note' => 'Shopify ချိတ်ဆက်မှု ရှိပြီးသား ကုန်ပစ္စည်းများနှင့် ဤစတိုး၏ ဂိုဒေါင်ရှိ ရွေ့လျားမှုများကိုသာ ပို့သည်။ အစုလိုက် လုပ်ဆောင်ချက်များ — ကုန်ပစ္စည်း ဖျက်ခြင်း၊ ဂိုဒေါင် ပြန်သတ်မှတ်ခြင်း — သည် ဖြစ်ရပ် မထုတ်ဘဲ စတော့ကို ရေးသဖြင့် အချိန်ဇယားသတ်မှတ်ထားသော inventory အဆင့်ကိုလည်း ဆက်ထားရန် အကြောင်းရင်းတစ်ခု ဖြစ်သည်။',
'Shopify_G_Nothing_Install' => 'ထပ်ထည့်သွင်းစရာ မရှိပါ',
