'Shopify_G_After' => 'ပြီးနောက်မှ',
'Shopify_G_Artisan_Note' => 'ခြွင်းချက်တစ်ခု: artisan command မှ ပြုလုပ်သော စတော့ ပြောင်းလဲမှုတွင် နောက်မှ လုပ်ဆောင်စရာ response မရှိသဖြင့် ၎င်းကို {queue} ပေါ်တွင် queue ထဲ ထည့်သည်။ ၎င်းတို့ကိုလည်း မြန်မြန် ပို့စေလိုပါက ထို queue ကို ရှင်းထုတ်ပါ:',
'Shopify_G_On_Schedule' => 'အချိန်ဇယားအတိုင်း',
'Shopify_G_On_Lower' => 'ဖွင့်',
'Shopify_G_Off_Lower' => 'ပိတ်',
'Shopify_G_Scheduled_Lead' => 'အရာအားလုံးကို အခါအားလျော်စွာ နှစ်ဖက်စလုံး ပြန်စစ်ဆေးသည်။ အချိန်နှင့်တပြေးညီထက် နှေးသော်လည်း instant push မသုံးသော shop များတွင် စတော့ကို ပို့ပေးသည့်အရာ၊ လွတ်သွားသော webhook ကို ဖမ်းယူသည့်အရာ ဖြစ်ပြီး catalog တစ်ခုလုံးကို ရွှေ့ရန် တစ်ခုတည်းသော နည်းလမ်း ဖြစ်သည်။',
'Shopify_G_Cron_Entry' => 'cron ထည့်သွင်းချက်',
'Shopify_G_Cron_Entry_Desc' => '၎င်းမပါဘဲ အချိန်ဇယားသတ်မှတ်ထားသည့်အရာ ဘာမှ မလုပ်ဆောင်ပါ။ စာကြောင်း တစ်ကြောင်း၊ ဤ module အတွက်သာ — သင် အချိန်ဇယား သတ်မှတ်ရန် ရွေးထားသော အခြားအရာများ၏ ဘေးတွင် ထည့်ပါ:',
'Shopify_G_Cron_Note' => 'အဆင့် ကြားကာလ အတိုဆုံးမှာ ငါးမိနစ် ဖြစ်သဖြင့် အစီအစဉ်တစ်ခု သုံးနိုင်သော အသေးဆုံး resolution မှာ ငါးမိနစ်တိုင်း ဖြစ်သည်။ ပိုကြမ်းသော entry သည် အနိမ့်ဆုံးအဖြစ် ဖြစ်လာသည် — {example} ဖြင့် 5 မိနစ်ဟု သတ်မှတ်ထားသော အဆင့်သည် 15 မိနစ်တိုင်း လုပ်ဆောင်မည်။ Windows တွင် Task Scheduler ကို သုံးပါ: program {program}၊ arguments {args}၊ started in {dir}။',
'Shopify_G_Switch_On_Plan' => 'ဖွင့်ပြီး အစီအစဉ်ကို ရွေးပါ',
'Shopify_G_Plan_Desc' => '{where} Switch က cron လုပ်ဆောင်ခွင့် ရှိမရှိကို ဆုံးဖြတ်ပြီး အစီအစဉ်က ၎င်း လုပ်ဆောင်မည့်အရာကို ဆုံးဖြတ်သည်။ {step} တစ်ခုသည် ကိုယ်ပိုင် ကြားကာလပါသော ဦးတည်ချက်တစ်ခုရှိ entity တစ်ခု ဖြစ်သည် — {first}၊ {second}။ ကိုယ်ပိုင် ဘောက်စ်ကို အလွတ်ထားသော အဆင့်မည်သည်မဆို မူလ ကြားကာလကို သုံးသည်။',
'Shopify_G_Step_Lower' => 'အဆင့်',
'Shopify_G_Plan_Note' => 'အစီအစဉ်ကို အလွတ်ထားပါက စတိုးသည် မူလ ကြားကာလဖြင့် အော်ဒါများကို ဆွဲယူပြီး စတော့ကို ပို့သည်၊ shop အများစု လိုချင်သည်မှာ ဤအတိုင်း ဖြစ်သည်။ အော်ဒါများသည် pull သာ ဖြစ်သည်: ဖောက်သည်က အော်ဒါ တင်သည့်နေရာမှာ Shopify ဖြစ်သည်။',
'Shopify_G_Schedule_On' => 'အချိန်ဇယား ဖွင့်',
