'Shopify_G_When_Step_Runs' => 'အဆင့်တစ်ခု အမှန်တကယ် လုပ်ဆောင်ချိန်',
'Shopify_G_When_Note' => 'ထိုအဆင့်တည်း နောက်ဆုံး {started}သည့်အချိန်မှ ၎င်း၏ ကြားကာလထက် ပိုကြာသွားသောအခါ run history မှ ဖတ်၍ အဆင့်သည် လုပ်ဆောင်ရန် အချိန်ရောက်သည်။ ထို့ကြောင့် ကိုယ်တိုင် စတင်သော sync က နောက် အလိုအလျောက် run ကို ရွှေ့ဆိုင်းပြီး ဆက်တိုက် မအောင်မြင်သော အဆင့်ကို tick တိုင်းမဟုတ်ဘဲ ၎င်း၏ ကြားကာလအလိုက် ပြန်ကြိုးစားသည်။ စတိုး၏ Overview တွင် အဆင့်တစ်ခုစီ၏ နောက်ဆုံး run၊ နောက်တစ်ကြိမ် လုပ်ရမည့်အချိန်နှင့် ပိတ်ဆို့ခံရပါက အကြောင်းရင်းကို ပြသည်။ ပထမ catalog push ကို အချိန်ဇယားတွင် မထည့်မီ ကိုယ်တိုင် run ပါ — {dryRun} ဖြင့် အရင် run ပါ။',
'Shopify_G_Started_Lower' => 'စတင်ခဲ့',
'Shopify_G_Where_Setting' => 'ဆက်တင်တစ်ခုစီ ရှိရာနေရာ',
