'Shopify_G_Img_3' => 'ဖိုင်အဖြစ် သိမ်းထားသော ပုံကို Shopify သို့ link မလုပ်ဘဲ {uploaded}သဖြင့် ဤ installation ကို အင်တာနက်မှ ဆက်သွယ်မရသော်လည်း အလုပ်ဖြစ်သည်။ ကူးထည့်ထားသော link အဖြစ် ထည့်သော ပုံကို ထို URL အတိုင်း Shopify ထံ ပေးပြီး ၎င်းကို အများပြည်သူ ဆက်သွယ်နိုင်ရမည်။',
'Shopify_G_Uploaded' => 'upload လုပ်',
