'Cr_Guide_T_Statuses' => 'အခြေအနေများ',
'Cr_Guide_Statuses_Note' => 'အခြေအနေများသည် ရှေ့သို့သာ ရွေ့လျားသောကြောင့် နောက်ကျရောက်သော အပ်ဒိတ်တစ်ခုက ပါဆယ်ကို နောက်ပြန်မဆွဲနိုင်ပါ။ ပို့ဆောင်ပြီးသော ပါဆယ်ကိုမူ ပြန်ပို့နေသည် သို့မဟုတ် ပြန်ပို့ပြီး ဟု အစီရင်ခံနိုင်ပါသေးသည်။',
'Cr_Guide_S_booked' => 'ပို့ဆောင်ရေးကုမ္ပဏီထံ အော်ဒါရှိနေပြီး မည်သူမျှ လာမယူရသေးပါ။ စာရင်းသွင်းမှုကို ယခုအချိန်တွင်သာ ပယ်ဖျက်နိုင်ပါသည်။',
'Cr_Guide_S_picked_up' => 'ပို့ဆောင်ရေးကုမ္ပဏီက ပါဆယ်ကို လာယူပြီးပါပြီ။',
'Cr_Guide_S_in_transit' => 'စခန်းများကြား ရွေ့လျားနေသည်၊ အကောက်ခွန်တွင် ရှိနေသည် သို့မဟုတ် ထိန်းထားသည်။',
'Cr_Guide_S_out_for_delivery' => 'ယနေ့ ပို့ဆောင်သူထံ ရှိနေသည်။',
'Cr_Guide_S_failed_attempt' => 'အိမ်တွင်မရှိ၊ ငြင်းပယ်ခံရ သို့မဟုတ် လိပ်စာမှားသည်။ ပို့ဆောင်ရေးကုမ္ပဏီက ထပ်ကြိုးစားမည် သို့မဟုတ် ပြန်ပို့ပါမည်။',
'Cr_Guide_S_delivered' => 'ဖောက်သည်ထံ လွှဲအပ်ပြီး။ COD ပမာဏသည် ပို့ဆောင်ရေးကုမ္ပဏီက ကောက်ခံပြီး ဖြစ်လာပါသည်။',
'Cr_Guide_S_returning' => 'သင့်ထံ ပြန်လာနေသည်။',
'Cr_Guide_S_returned' => 'သင့်ထံ ပြန်ရောက်ပြီး- စစ်ဆေးရန် ပြန်အမ်းများ တွင် စောင့်ဆိုင်းနေသည် သို့မဟုတ် အလိုအလျောက် စတော့ပြန်ထည့်ပြီး။',
'Cr_Guide_S_cancelled' => 'စာရင်းသွင်းမှုကို ပယ်ဖျက်ခဲ့သည်။',
'Cr_Guide_T_Booking' => 'အော်ဒါများ စာရင်းသွင်းခြင်း',
'Cr_Guide_B_Booking' => 'ပို့ဆောင်ရေးကုမ္ပဏီထံ ပို့ရန် သည် အရောင်းမှ ဖောင်ကို ဖြည့်ပေးပါသည်- လက်ခံသူ၊ လိပ်စာ၊ COD အဖြစ် ကျန်ငွေပမာဏနှင့် ကုန်ပစ္စည်းများ၏ အလေးချိန်။ ကိုယ်ပိုင်မြို့စာရင်းရှိသော ပို့ဆောင်ရေးကုမ္ပဏီများသည် ရွေးချယ်စရာကို ပြသပြီး သင့်ရွေးချယ်မှုကို ထိုမြို့အတွက် မှတ်ထားပါသည်။ Aggregator များ၊ DHL၊ FedEx၊ UPS နှင့် Lalamove တို့သည် နှုန်းထားများ နှိုင်းယှဉ်ရန် ကို ပေးပါသည်- ဈေးနှုန်းတစ်ခုကို ရွေးပြီး စာရင်းသွင်းရန် ဖြင့် ဝယ်ယူပါ။ အရောင်းစာရင်းမှ အရောင်းများစွာကို တစ်ပြိုင်နက် စာရင်းသွင်းနိုင်ပါသည်။',
'Cr_Guide_T_Cod' => 'ပစ္စည်းရောက်ငွေချေ',
'Cr_Guide_B_Cod' => 'COD ပါဆယ်တစ်ခုသည် မကောက်ခံရသေး မှ ပို့ဆောင်ရေးကုမ္ပဏီက ကောက်ခံပြီး (ပို့ဆောင်ချိန်တွင်) သို့၊ ထို့နောက် သင့်ထံ ပေးချေပြီး သို့ ရွေ့လျားပါသည်။ ပေးချေမှုများကို အစီရင်ခံသော ပို့ဆောင်ရေးကုမ္ပဏီများသည် နောက်ဆုံးအဆင့်ကို ကိုယ်တိုင်ရွှေ့ပါသည်၊ အခြားကုမ္ပဏီများအတွက် COD အပ်ဒိတ်လုပ်ရန် ကို အသုံးပြုပါ။ ပို့ဆောင်ရေး ဆက်တင်များတွင် အကောင့်ရွေးထားပါက ပေးချေမှုကို အရောင်းတွင် ငွေပေးချေမှုအဖြစ် မှတ်တမ်းတင်ပါသည်။ ပါဆယ်ပြီးဆုံးသည်နှင့် ပို့ဆောင်ရေးအခကြေးငွေများကို အသုံးစရိတ်အဖြစ် သိမ်းဆည်းနိုင်ပါသည်။',
'Cr_Guide_T_Returns' => 'ပြန်ပို့ထားသော ပါဆယ်များ',
'Cr_Guide_B_Returns' => 'မူလအားဖြင့် ပြန်ပို့ပါဆယ်သည် ပို့ဆောင်ရေး ပို့ဆောင်မှုများ ရှိ စစ်ဆေးရန် ပြန်အမ်းများ အောက်တွင် စောင့်ဆိုင်းပါသည်။ စတော့ပြန်ထည့်ရန် သည် အော်ဒါတစ်ခုလုံးအတွက် အရောင်းပြန်အမ်းကို ဖန်တီးပြီး ပစ္စည်းများကို စတော့ထဲ ပြန်ထည့်ပါသည်။ ပယ်ရန် သည် ပျက်စီးသော သို့မဟုတ် ပျောက်ဆုံးသော ပါဆယ်များအတွက် ဘာမှ ပြန်မထည့်ပါ။ ယင်းအစား ပို့ဆောင်ရေး ဆက်တင်များတွင် အလိုအလျောက် စတော့ပြန်ထည့်ရန် သတ်မှတ်နိုင်ပါသည်။',
'Cr_Guide_T_Customers' => 'ဖောက်သည် မက်ဆေ့ချ်များနှင့် ခြေရာခံစာမျက်နှာ',
'Cr_Guide_B_Customers' => 'ပို့ဆောင်ရေး ဆက်တင်များရှိ ဖောက်သည်အသိပေးချက်များသည် သင်အမှန်ခြစ်ထားသော အခြေအနေများတွင် SMS၊ အီးမေးလ် သို့မဟုတ် WhatsApp ကို ပါဆယ်တစ်ခုလျှင် တစ်ကြိမ်စီ သင့်ကိုယ်ပိုင်စာသားဖြင့် ပို့ပါသည်။ သင့်အွန်လိုင်းစတိုးရှိ ခြေရာခံစာမျက်နှာသည် ဖောက်သည်များကို ခြေရာခံနံပါတ်၊ သို့မဟုတ် အော်ဒါနံပါတ်နှင့် ဖုန်းဖြင့် ပါဆယ်ကို လိုက်ကြည့်ခွင့်ပြုပါသည်။ ပါဆယ်များကို မကြာခဏ ပြန်ပို့သော ဖောက်သည်များသည် သင်စာရင်းသွင်းသည့်အခါ ပြန်အမ်းအန္တရာယ် တံဆိပ်ကို ရရှိပါသည်။',
'Cr_Guide_T_Labels' => 'တံဆိပ်များ',
'Cr_Guide_B_Labels' => 'တံဆိပ် ပုံနှိပ်ရန် သည် ပို့ဆောင်ရေးကုမ္ပဏီက ကိုယ်ပိုင်တံဆိပ် (PDF၊ လင့်ခ် သို့မဟုတ် ပုံ) ထုတ်ပေးပါက ထိုတံဆိပ်ကို ပေးပါသည်၊ မဟုတ်ပါက ခြေရာခံဘားကုဒ်နှင့် ကောက်ခံရမည့်ပမာဏပါသော Stocky တံဆိပ်ကို ပေးပါသည်။ ပုံနှိပ်ရန် ဤဆိုက်အတွက် pop-up များကို ခွင့်ပြုပါ။ DHL၊ FedEx နှင့် UPS တို့သည် ၎င်းတို့၏ တံဆိပ်ကို စာရင်းသွင်းချိန်တွင် တစ်ကြိမ်သာ ပေးသောကြောင့် Stocky က ပြန်ပုံနှိပ်ရန် သိမ်းထားပါသည်။',
'Cr_Guide_T_Faq' => 'ပြဿနာဖြေရှင်းခြင်း',
'Cr_Guide_Q_Test' => 'ချိတ်ဆက်မှု စမ်းသပ်ခြင်း မအောင်မြင်ပါ',
'Cr_Guide_A_Test' => 'စမ်းသပ်မုဒ် ကီးများကို စမ်းသပ်မုဒ်နှင့်၊ တိုက်ရိုက် ကီးများကို တိုက်ရိုက်မုဒ်နှင့် တွဲသုံးရပါမည်၊ ၎င်းတို့ မတူညီပါ။ တိကျသော အကြောင်းရင်းအတွက် ပို့ဆောင်ရေး မှတ်တမ်းများ ကို ဖွင့်ပြီး ပို့ဆောင်ရေးကုမ္ပဏီ၏ အဖြေကို ဖတ်ပါ။',
'Cr_Guide_Q_City' => 'ပို့ဆောင်ရေးကုမ္ပဏီက မြို့ သို့မဟုတ် လိပ်စာကို ငြင်းပယ်သည်',
'Cr_Guide_A_City' => 'စာရင်းသွင်းဖောင်ရှိ ပို့ဆောင်ရေးမြို့စာရင်းမှ မြို့ကို ရွေးပါ၊ ပို့ဆောင်ရေးကုမ္ပဏီများသည် ၎င်းတို့၏ ကိုယ်ပိုင်အမည်များကိုသာ လက်ခံပါသည်။ စာပို့လိပ်စာများဖြင့် အလုပ်လုပ်သော ပို့ဆောင်ရေးကုမ္ပဏီများသည် ပြည်နယ်၊ စာပို့သင်္ကေတနှင့် စာလုံးနှစ်လုံး နိုင်ငံကုဒ်ကိုလည်း လိုအပ်ပါသည်။',
'Cr_Guide_Q_Webhook' => 'အခြေအနေများ အလိုအလျောက် မပြောင်းလဲပါ',
'Cr_Guide_A_Webhook' => 'အပ်ဒိတ်ပို့ပေးသော ပို့ဆောင်ရေးကုမ္ပဏီများအတွက် webhook URL ကို ပို့ဆောင်ရေးကုမ္ပဏီတွင် မှတ်ပုံတင်ထားကြောင်း စစ်ဆေးပါ- ပို့ဆောင်ရေး မှတ်တမ်းများ သည် လက်ခံရရှိသော အပ်ဒိတ်တိုင်း သို့မဟုတ် ငြင်းပယ်ခံရသည့် အကြောင်းရင်း (ဥပမာ လျှို့ဝှက်ကီးမှားခြင်း) ကို ပြသပါသည်။ အခြားပို့ဆောင်ရေးကုမ္ပဏီများကို ပို့ဆောင်ရေး ဆက်တင်များရှိ အချိန်ဇယားအတိုင်း စစ်ဆေးပြီး ယခု အခြေအနေ စစ်ဆေးရန် သည် ချက်ချင်း မေးမြန်းပါသည်။',
'Cr_Guide_Q_Stuck' => 'ပို့ဆောင်မှုတစ်ခုတွင် အခြေအနေ စစ်ဆေးမှု အမှား ပြသနေသည်',
'Cr_Guide_A_Stuck' => 'ပို့ဆောင်ရေးကုမ္ပဏီက နောက်ဆုံးစစ်ဆေးမှုများကို ငြင်းပယ်ခဲ့ပါသည်၊ အကြောင်းရင်းကို ပို့ဆောင်မှုနှင့် ပို့ဆောင်ရေး မှတ်တမ်းများ တွင် တွေ့နိုင်ပါသည်။ ထပ်ခါထပ်ခါ မအောင်မြင်ပြီးနောက် ပို့ဆောင်မှုကို အလိုအလျောက် မစစ်ဆေးတော့ပါ- အကြောင်းရင်းကို ပြင်ဆင်ပြီး ယခု အခြေအနေ စစ်ဆေးရန် ကို အသုံးပြုပါ။',
'Cr_Guide_Q_Label' => 'တံဆိပ် ပုံနှိပ်သည့်အခါ ဘာမှ မပွင့်ပါ',
'Cr_Guide_A_Label' => 'သင့်ဘရောက်ဆာက pop-up ကို ပိတ်ဆို့ထားပါသည်။ ဤဆိုက်အတွက် pop-up များကို ခွင့်ပြုပြီး ထပ်ကြိုးစားပါ။',
'Cr_Guide_Q_Cod' => 'COD ပေးချေမှုကို အရောင်းတွင် မှတ်တမ်းမတင်ခဲ့ပါ',
