'Tfa_Guide_Require_Text' => 'ဤကတ်ပေါ်ရှိ "နှစ်ဆင့် အထောက်အထားစိစစ်ခြင်းကို မဖြစ်မနေ လိုအပ်စေရန်" ကို ဖွင့်ပြီး ၎င်းကို အသုံးပြုရမည့် အခန်းကဏ္ဍများကို ရွေးပါ — သို့မဟုတ် အသုံးပြုသူတိုင်းအတွက် စာရင်းကို ဗလာထားပါ။ သိမ်းရန် တင်သွင်းရန် ကို နှိပ်ပါ။',
