'Tfa_Guide_Require_Note' => 'လိုအပ်ထားသော အသုံးပြုသူများသည် ၎င်းတို့၏ ပရိုဖိုင်မှ ၎င်းကို ပိတ်၍ မရပါ။',
'Tfa_Guide_Trust_Title' => 'ယုံကြည်ရသော စက်များ',
