'Tfa_Guide_Trust_Note' => 'အရေအတွက်ကို လျှော့ချခြင်းသည် ယုံကြည်ပြီးသား စက်များ၏ ကာလကို တိုစေပြီး 2FA ကို ပိတ်ခြင်း သို့မဟုတ် ပြန်လည်သတ်မှတ်ခြင်းသည် ၎င်းတို့အားလုံးကို မေ့ပစ်ပါသည်။',
'Tfa_Guide_Lost_Title' => 'ဖုန်းပျောက်ပြီး ပြန်လည်ရယူရေး ကုဒ်များ မရှိခြင်း',
'Tfa_Guide_Lost_Text' => 'အသုံးပြုသူများ စာမျက်နှာတွင် 2FA ရှိသော အသုံးပြုသူများသည် 2FA ကော်လံ၌ "ဖွင့်" ဟု ပြပါသည်။ လုပ်ဆောင်ချက်များရှိ ဒိုင်းခလုတ်က ၎င်းကို ပြန်လည်သတ်မှတ်ပါသည်- အသုံးပြုသူသည် စကားဝှက်ဖြင့်သာ အကောင့်ဝင်ပြီး app ကို ပြန်လည်တပ်ဆင်ပါသည် (လိုအပ်ထားပါက တပ်ဆင်ရန် တောင်းဆိုခံရပါမည်)။',
'Tfa_Guide_Lost_Warn' => 'ပြန်လည်မသတ်မှတ်မီ မည်သူတောင်းဆိုနေသည်ကို အတည်ပြုပါ — ပြန်လည်သတ်မှတ်ခြင်းသည် ထိုအကောင့်အား 2FA ပေးသော ကာကွယ်မှုကို ဖယ်ရှားပါသည်။',
'Tfa_Guide_Open_Users' => 'အသုံးပြုသူများကို ဖွင့်ရန်',
'Tfa_Guide_Mobile_Title' => 'မိုဘိုင်း app နှင့် API',
'Tfa_Guide_Mobile_Text' => 'မိုဘိုင်း app နှင့် API token endpoint တို့သည်လည်း ထိုကုဒ်ကိုပင် တောင်းပါသည်။ မတပ်ဆင်ရသေးသော အသုံးပြုသူအတွက် 2FA လိုအပ်ထားပါက ၎င်းကို တပ်ဆင်ရန် ဝဘ်တွင် တစ်ကြိမ် အကောင့်ဝင်ရပါမည်။',
'Tfa_Guide_Protect_Title' => 'ပါဝင်ပြီးသား ကာကွယ်မှု',
'Tfa_Guide_Protect_1' => 'အထက်ပါ ပိတ်ဆို့ဆက်တင်များ မည်သို့ပင်ရှိစေ ကုဒ်မှား ၅ ကြိမ်ဖြစ်ပါက ထိုအသုံးပြုသူအတွက် ကုဒ်ထည့်ခြင်းကို မိနစ် ၁၅ ကြာ ပိတ်ဆို့ပါမည်။',
'Tfa_Guide_Protect_2' => 'ကုဒ်တစ်ခုစီနှင့် ပြန်လည်ရယူရေး ကုဒ်တစ်ခုစီသည် တစ်ကြိမ်သာ အလုပ်လုပ်ပါသည်။',
'Tfa_Guide_Protect_3' => '"အကောင့်ဝင်ရောက်မှု လှုပ်ရှားမှုကို မှတ်တမ်းတင်ရန်" ဖွင့်ထားပါက ကုဒ်မှားများကို အကောင့်ဝင်ရောက်မှု လှုပ်ရှားမှု စာရင်းတွင် "2FA ကုဒ် မှားသည်" အဖြစ် ပြပါမည်။',
'Tfa_Guide_Trouble_Title' => 'ပြဿနာဖြေရှင်းခြင်း',
'Tfa_Guide_Faq_Clock_Q' => 'ကုဒ်အသစ်ဖြင့်ပင် “ထိုကုဒ်သည် မမှန်ကန်ပါ” ဟု ပြခြင်း',
'Tfa_Guide_Faq_Clock_A' => 'ဖုန်းနာရီ မှားနေနိုင်ပါသည်။ ကုဒ်များသည် အချိန်ပေါ် မူတည်ပါသည်- ဖုန်း၏ ရက်စွဲနှင့် အချိန်ကို အလိုအလျောက် (ကွန်ရက်အချိန်) သို့ သတ်မှတ်ပြီး နောက်ကုဒ်ကို စမ်းကြည့်ပါ။',
'Tfa_Guide_Faq_Phone_Q' => 'ဖုန်းအသစ်သို့ ပြောင်းခြင်း',
'Tfa_Guide_Faq_Phone_A' => 'authenticator app ၏ ကိုယ်ပိုင် လွှဲပြောင်းခြင်း လုပ်ဆောင်ချက်ကို အသုံးပြုပါ၊ သို့မဟုတ် ပရိုဖိုင်တွင် 2FA ကို ပိတ်ပြီး ဖုန်းအသစ်ဖြင့် ပြန်ဖွင့်ပါ (လိုအပ်ထားပါက ၎င်းအစား စီမံခန့်ခွဲသူကို ပြန်လည်သတ်မှတ်ပေးရန် တောင်းဆိုပါ)။',
'Tfa_Guide_Faq_Locked_Q' => '“မမှန်ကန်သော ကုဒ်များ အလွန်များနေသည်”',
'Tfa_Guide_Faq_Locked_A' => 'ပြထားသော အချိန် (မိနစ် ၁၅ အထိ) စောင့်ပါ၊ သို့မဟုတ် အသုံးပြုသူ၏ 2FA ကို စီမံခန့်ခွဲသူအား ပြန်လည်သတ်မှတ်ခိုင်းပါ။',
'Tfa_Guide_Faq_Key_Q' => 'ဆာဗာ ပြောင်းရွှေ့ပြီးနောက် 2FA ရှိသူ မည်သူမျှ အကောင့်ဝင်၍ မရခြင်း',
'Tfa_Guide_Faq_Key_A' => '2FA လျှို့ဝှက်ချက်များကို .env ဖိုင်ရှိ APP_KEY ဖြင့် ကုဒ်ဝှက်ထားပါသည်။ app ကို ပြောင်းရွှေ့ သို့မဟုတ် ပြန်လည်ရယူသည့်အခါ APP_KEY ကို အတူတူထားပါ၊ ၎င်းပြောင်းလဲသွားပါက 2FA မရှိသော စီမံခန့်ခွဲသူတစ်ဦးက သက်ရောက်ခံရသော အသုံးပြုသူများကို ပြန်လည်သတ်မှတ်ရပါမည်။',
'Tfa_Guide_Button' => 'လမ်းညွှန်',
'Tfa_Guide_Title' => 'နှစ်ဆင့် အထောက်အထားစိစစ်ခြင်း လမ်းညွှန်',
'Sec_2fa_Pending' => ':count ဦး တပ်ဆင်ရန် ကျန်သေးသည်',
'Sec_2fa_See_Who' => 'မည်သူဖြစ်သည် ကြည့်ရန်',
'Sec_2fa_Grace_Off' => 'မရှိ — နောက်တစ်ကြိမ် အကောင့်ဝင်ချိန်တွင် တပ်ဆင်ရန်',
'Sec_2fa_Applied' => 'အသုံးပြုသူ :count ဦးကို အကောင့်မှ ထုတ်ပြီးပါပြီ။',
'Tfa_Guide_Rollout_Title' => 'အသုံးပြုသူတိုင်းထံ ဖြန့်ချိရန်',
'Tfa_Guide_Rollout_1' => 'အဆင့်များကို သိစေရန် သင့်ကိုယ်ပိုင်အကောင့် (ပရိုဖိုင်) အတွက် အရင်ဖွင့်ပါ။',
'Tfa_Guide_Rollout_2' => 'မည်သည့် app ကို ထည့်သွင်းရမည်ကိုနှင့် အကောင့်ဝင်ချိန်တွင် တပ်ဆင်ရန် တစ်မိနစ်ခန့်သာ ကြာကြောင်း သင့်အဖွဲ့ကို အသိပေးပါ။',
'Tfa_Guide_Rollout_3' => '"နှစ်ဆင့် အထောက်အထားစိစစ်ခြင်းကို မဖြစ်မနေ လိုအပ်စေရန်" ကို ဖွင့်ပြီး "လိုအပ်သည့်သူများ" ကို ဗလာထားကာ (= အသုံးပြုသူတိုင်း) လိုအပ်ပါက ကျေးဇူးပြုကာလ တစ်ခု ရွေးပါ။ တင်သွင်းရန် ကို နှိပ်ပါ။',
'Tfa_Guide_Rollout_4' => 'အကောင့်ဝင်ပြီးသားသူများ နောက်ပိုင်း အကောင့်ဝင်ချိန်ကို မစောင့်ဘဲ ယခုပင် တပ်ဆင်စေရန် "2FA မရှိသော အသုံးပြုသူများကို အကောင့်မှ ထုတ်ရန်" ကို နှိပ်ပါ။ သင်ကမူ အကောင့်ဝင်ထားဆဲ ဖြစ်ပါမည်။',
'Tfa_Guide_Rollout_5' => 'ဤကတ်ပေါ်ရှိ ရေတွက်ကိရိယာ သို့မဟုတ် အသုံးပြုသူများ စာမျက်နှာရှိ "တပ်ဆင်ရန် လိုအပ်သည်" စစ်ထုတ်မှုဖြင့် တိုးတက်မှုကို စောင့်ကြည့်ပါ။',
'Tfa_Guide_Rollout_Note' => 'ကျေးဇူးပြုကာလ ရှိပါက တပ်ဆင်မှုစခရင်သည် နောက်ဆုံးရက်အထိ “နောက်မှ သတိပေးပါ” ကို ပြပြီး ထို့နောက်တွင် အကောင့်ဝင်ရန် တပ်ဆင်မှု လိုအပ်ပါမည်။',
'Tfa_Guide_Customers_Title' => 'ဖောက်သည် အကောင့်များ (စတိုးနှင့် ဖောက်သည် portal)',
'Tfa_Guide_Customers_Text' => 'ဖောက်သည်များသည်လည်း ၎င်းတို့၏ ကိုယ်ပိုင်အကောင့်များကို ကာကွယ်နိုင်ပါသည်။ ၎င်းသည် ဖောက်သည်တစ်ဦးစီအတွက် ရွေးချယ်နိုင်ပြီး ဘယ်တော့မှ အတင်းအကျပ် မလုပ်ပါ- စတိုး ဆက်တင်များ → မှတ်ပုံတင်ခြင်း ဝင်ရောက်ခွင့် ထိန်းချုပ်မှု (အွန်လိုင်းစတိုး) နှင့် ဖောက်သည် Portal → Portal ဆက်တင်များ (ဖောက်သည် portal) အောက်တွင် ဖွင့်ပါ။',
'Tfa_Guide_Customers_1' => 'ဖောက်သည်များသည် ကျွန်ုပ်၏အကောင့် (စတိုး) သို့မဟုတ် ပရိုဖိုင် (portal) မှ ၎င်းကို ဖွင့်ပါသည်။',
'Tfa_Guide_Customers_2' => '၎င်းတို့သည် အီးမေးလ်ဖြင့် ပို့သော ကုဒ် — အလွယ်ဆုံး၊ app မလိုပါ — သို့မဟုတ် ပြန်လည်ရယူရေး ကုဒ်များပါသော authenticator app ကို ရွေးချယ်ပါသည်။',
'Tfa_Guide_Customers_3' => 'အီးမေးလ်ဖြင့် ပို့သော ကုဒ်များအတွက် အလုပ်လုပ်သော မေးလ်ဆက်တင်များ (ဆက်တင်များ → မေးလ် ဆက်တင်များ) လိုအပ်ပါသည်။ ၎င်းတို့သည် မိနစ် ၁၀ အကြာတွင် သက်တမ်းကုန်ပါသည်။',
'Tfa_Guide_Customers_4' => 'နောက်ပိုင်းတွင် ရွေးချယ်မှုကို ပိတ်ပါက တပ်ဆင်မှုအသစ်များ ရပ်သွားမည်ဖြစ်ပြီး ၎င်းကို အသုံးပြုနေပြီးသား ဖောက်သည်များကိုမူ ဆက်လက်မေးမြန်းမည်ဖြစ်ကာ ၎င်းတို့ကိုယ်တိုင် ပိတ်နိုင်ပါသည်။',
'Tfa_Required_Grace_Notice' => 'သင့်စီမံခန့်ခွဲသူက နှစ်ဆင့် အထောက်အထားစိစစ်ခြင်းကို လိုအပ်ထားပါသည်။ :date အထိ အကောင့်ဝင်ချိန်တွင် ၎င်းကို ရွှေ့ဆိုင်းနိုင်ပြီး ထို့နောက်တွင် တပ်ဆင်မှု လိုအပ်ပါမည်။',
'Tfa_Filter_All' => '2FA: အသုံးပြုသူ အားလုံး',
'Tfa_Needs_Setup_Help' => 'စနစ် ဆက်တင်များ > လုံခြုံရေး မှ လိုအပ်ထားသည်၊ နောက်တစ်ကြိမ် အကောင့်ဝင်ချိန်တွင် တပ်ဆင်ရန် တောင်းဆိုပါမည်။',
'Tfa_Needs_Setup' => 'တပ်ဆင်ရန် လိုအပ်သည်',
'Tfa_Filter_On' => '2FA ဖွင့်',
'Tfa_Filter_Off' => '2FA ပိတ်',
'Tfa_Filter_Pending' => 'တပ်ဆင်ရန် လိုအပ်သည် (မဖြစ်မနေ)',
'Store_Customer_2fa' => 'နှစ်ဆင့် အတည်ပြုခြင်း',
'Store_Customer_2fa_Help' => 'ဖောက်သည်များအား အီးမေးလ်ဖြင့် ပို့သော ကုဒ် သို့မဟုတ် authenticator app မှ ကုဒ်ဖြင့် ၎င်းတို့၏ အကောင့်ကို ကာကွယ်ခွင့်ပြုပြီး ကျွန်ုပ်၏အကောင့် မှ ဖွင့်နိုင်ပါသည်။ ဖောက်သည်တစ်ဦးစီအတွက် ရွေးချယ်နိုင်ပါသည်။',
'Portal_2fa' => 'နှစ်ဆင့် အတည်ပြုခြင်း',
'Portal_2fa_Help' => 'ဖောက်သည်များအား အီးမေးလ်ဖြင့် ပို့သော ကုဒ် သို့မဟုတ် authenticator app မှ ကုဒ်ဖြင့် ၎င်းတို့၏ portal login ကို ကာကွယ်ခွင့်ပြုပြီး ၎င်းတို့၏ ပရိုဖိုင်မှ ဖွင့်နိုင်ပါသည်။ ဖောက်သည်တစ်ဦးစီအတွက် ရွေးချယ်နိုင်ပါသည်။',
